import java.util.HashMap;
import java.util.Map;

public class Solution {
    interface Relogio {
        long agoraMillis();
    }

    static class RateLimiterJanelaFixa {
        private final int limite;
        private final long janelaMs;
        private final Relogio relogio;
        private final Map<String, Long> contadores = new HashMap<>();
        private final Map<String, Long> expiracoes = new HashMap<>();

        RateLimiterJanelaFixa(int limite, long janelaMs, Relogio relogio) {
            if (limite <= 0) throw new IllegalArgumentException("limite invalido");
            if (janelaMs <= 0) throw new IllegalArgumentException("janela invalida");
            if (relogio == null) throw new IllegalArgumentException("relogio obrigatorio");
            this.limite = limite;
            this.janelaMs = janelaMs;
            this.relogio = relogio;
        }

        boolean permitir(String usuario) {
            exigirUsuario(usuario);
            long agora = relogio.agoraMillis();
            String chave = chave(usuario);
            expirarSeNecessario(chave, agora);
            long atual = contadores.merge(chave, 1L, Long::sum);
            expiracoes.putIfAbsent(chave, agora + janelaMs);
            return atual <= limite;
        }

        long restantes(String usuario) {
            exigirUsuario(usuario);
            long agora = relogio.agoraMillis();
            String chave = chave(usuario);
            expirarSeNecessario(chave, agora);
            long atual = contadores.getOrDefault(chave, 0L);
            return Math.max(0, limite - atual);
        }

        private void expirarSeNecessario(String chave, long agora) {
            Long expira = expiracoes.get(chave);
            if (expira != null && agora >= expira) {
                contadores.remove(chave);
                expiracoes.remove(chave);
            }
        }

        private String chave(String usuario) {
            return "rl:" + usuario;
        }

        private void exigirUsuario(String usuario) {
            if (usuario == null || usuario.isBlank()) {
                throw new IllegalArgumentException("usuario obrigatorio");
            }
        }
    }
}

