import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    static class RelogioFake implements Solution.Relogio {
        long agora = 0;
        public long agoraMillis() { return agora; }
        void avancar(long ms) { agora += ms; }
    }

    @Test void limitaNaJanela() {
        var relogio = new RelogioFake();
        var rl = new Solution.RateLimiterJanelaFixa(3, 60_000, relogio);

        assertTrue(rl.permitir("ana"));
        assertTrue(rl.permitir("ana"));
        assertTrue(rl.permitir("ana"));
        assertFalse(rl.permitir("ana"));
        assertEquals(0, rl.restantes("ana"));
    }

    @Test void restantesDecrementa() {
        var relogio = new RelogioFake();
        var rl = new Solution.RateLimiterJanelaFixa(5, 60_000, relogio);
        assertEquals(5, rl.restantes("ana"));
        rl.permitir("ana");
        rl.permitir("ana");
        assertEquals(3, rl.restantes("ana"));
    }

    @Test void viradaDeJanelaLibera() {
        var relogio = new RelogioFake();
        var rl = new Solution.RateLimiterJanelaFixa(2, 60_000, relogio);
        assertTrue(rl.permitir("ana"));
        assertTrue(rl.permitir("ana"));
        assertFalse(rl.permitir("ana"));

        relogio.avancar(60_000);
        assertTrue(rl.permitir("ana"));
        assertEquals(1, rl.restantes("ana"));
    }

    @Test void expiracaoZeraContador() {
        var relogio = new RelogioFake();
        var rl = new Solution.RateLimiterJanelaFixa(2, 10_000, relogio);
        assertTrue(rl.permitir("ana"));
        assertTrue(rl.permitir("ana"));
        assertFalse(rl.permitir("ana"));

        relogio.avancar(9_000);
        assertFalse(rl.permitir("ana"));
        relogio.avancar(1_000);
        assertTrue(rl.permitir("ana"));
    }

    @Test void usuariosSaoIndependentes() {
        var relogio = new RelogioFake();
        var rl = new Solution.RateLimiterJanelaFixa(1, 60_000, relogio);
        assertTrue(rl.permitir("ana"));
        assertFalse(rl.permitir("ana"));
        assertTrue(rl.permitir("bruno"));
        assertEquals(0, rl.restantes("ana"));
        assertEquals(0, rl.restantes("bruno"));
    }

    @Test void validacoes() {
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.RateLimiterJanelaFixa(0, 1000, () -> 0));
        assertThrows(IllegalArgumentException.class,
            () -> new Solution.RateLimiterJanelaFixa(1, 0, () -> 0));
        var rl = new Solution.RateLimiterJanelaFixa(1, 1000, () -> 0);
        assertThrows(IllegalArgumentException.class, () -> rl.permitir(" "));
    }
}
